function startStage3(){document.getElementById("timer").textContent="";let n=0,e=null;const t=[{id:"red",name:"🔴 Power Lead",port:"POWER PORT"},{id:"blue",name:"🔵 ECG Lead",port:"ECG PORT"},{id:"yellow",name:"🟡 Charging Lead",port:"CHARGE PORT"},{id:"green",name:"🟢 Safety Lead",port:"SAFETY PORT"}];shuffle(t),stageContent.innerHTML=`\n\n    <div class="card repair-stage">\n\n\n        <h1>\n            ⚡ Defibrillator Repair\n        </h1>\n\n\n        <p class="stage-description">\n\n            The defibrillator system has failed.\n            Connect all cables to restore the device.\n\n        </p>\n\n\n\n\n        <div class="defib-device">\n\n\n            <h2>\n                ⚡ DEFIBRILLATOR\n            </h2>\n\n\n            <div class="device-status">\n\n                STATUS:\n                <span id="defib-status">\n\n                    ERROR ❌\n\n                </span>\n\n            </div>\n\n\n        </div>\n\n\n\n\n\n        <h3>\n\n            Select a cable then select its port\n\n        </h3>\n\n\n\n\n        <div class="repair-mobile-layout">\n\n\n\n            <div class="wire-panel">\n\n\n                ${t.map((n=>`\n\n                    <button\n\n                        class="wire"\n\n                        data-wire="${n.id}">\n\n                        ${n.name}\n\n                    </button>\n\n\n                `)).join("")}\n\n\n\n            </div>\n\n\n\n\n\n            <div class="port-panel">\n\n\n                <button\n\n                    class="port"\n\n                    data-port="red">\n\n                    POWER PORT\n\n                </button>\n\n\n\n                <button\n\n                    class="port"\n\n                    data-port="blue">\n\n                    ECG PORT\n\n                </button>\n\n\n\n                <button\n\n                    class="port"\n\n                    data-port="yellow">\n\n                    CHARGE PORT\n\n                </button>\n\n\n\n                <button\n\n                    class="port"\n\n                    data-port="green">\n\n                    SAFETY PORT\n\n                </button>\n\n\n\n            </div>\n\n\n\n        </div>\n\n\n\n\n\n        <div\n            id="repair-status"\n            class="status-box">\n\n            Select a cable\n\n        </div>\n\n\n\n    </div>\n\n    `;const a=document.getElementById("repair-status");document.querySelectorAll(".wire").forEach((n=>{n.onclick=()=>{n.classList.contains("connected")||(document.querySelectorAll(".wire").forEach((n=>n.classList.remove("selected"))),n.classList.add("selected"),e=n.dataset.wire,a.textContent="Now select the matching port")}})),document.querySelectorAll(".port").forEach((t=>{t.onclick=()=>{if(e){if(!t.classList.contains("connected"))if(e===t.dataset.port){t.classList.add("connected"),t.innerHTML="✅ CONNECTED";const i=document.querySelector(`.wire[data-wire="${e}"]`);i.classList.add("connected"),i.disabled=!0,n++,playSound("success"),a.textContent=`${n}/4 connections completed`,e=null,4===n&&runDiagnostic()}else playSound("failure"),gameOver("Wrong connection detected.<br><br>Hardware failure.")}else a.textContent="Select a cable first"}}))}function runDiagnostic(){stageContent.innerHTML='\n\n    <div class="card">\n\n\n        <h1>\n            🔍 System Diagnostic\n        </h1>\n\n\n        <br>\n\n\n        <p>\n            Checking Power Module...\n            ✅\n        </p>\n\n\n        <p>\n            Checking Charging Circuit...\n            ✅\n        </p>\n\n\n        <p>\n            Checking Patient Pads...\n            ✅\n        </p>\n\n\n        <br>\n\n\n        <h2>\n            Defibrillator Ready ⚡\n        </h2>\n\n\n    </div>\n\n    ',playSound("success"),setTimeout((()=>{transition("⚡ Defibrillator Online","Emergency shock system ready. Patient requires immediate intervention.",(()=>{updatePatientState("improving"),completedStage=3,stageCompleted()}))}),2e3)}